window.kbPageData["views/entry/k-4f0ccba171d29d0b"] = {"key":"entry/k-4f0ccba171d29d0b","state":{"route":"entry/k-4f0ccba171d29d0b"},"node":{"id":"k-4f0ccba171d29d0b","mode":"k","title":"按比例分配","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["按比例分配时各部分等于总量乘以该部分份数占比","按比例分配时各部分等于总量乘以该部分份数占总份数的比例","按比例分配时个体所得等于可分配总量乘以其所占比例","按比例分配时份额等于可分配总量乘以所占比例"],"qs":["国考 2023 副省级 行测#73","国考 2023 地市级 行测#68","国考 2025 地市级 行测#67","国考 2025 行政执法 行测#67"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":2,"repeatPositions":2,"directorySummary":"已知总量和各部分之比，且这些部分合起来等于总量时，各部分的量等于总量乘以该部分份数占总份数的比例。","review":{"definition":"已知总量和各部分之比，且这些部分合起来等于总量时，各部分的量等于总量乘以该部分份数占总份数的比例。","explanation":"员工只在部门之间调动，总人数仍为210。调动后的甲、丙、丁共占10份，每份21人，因此甲63人、丁84人。甲人数未变，原丁比甲少10人，原有53人。乙并入丁的人数为84−53＝31，再加上调到丙的20人，原乙共有51人。","references":[],"evidence":"甲、丙、丁三个部门的员工数之比为3：3：4","disposition":"独立词条","basis":"据原题和解析编释。","title":"按比例分配","related":[],"examFocus":{"国考 2023 副省级 行测#73":"把公司总利润、可分配利润和个人分红分开，利用分配比例固定的条件比较各年利润和甲的分红。","国考 2025 地市级 行测#67":"用总人数和调动后的比例确定各部门现有人数，再比较调动前后的人数，追踪原乙部门员工的去向。"}},"readings":[{"origin":"k-4f0ccba171d29d0b","title":"按比例分配","qs":["国考 2025 地市级 行测#67"],"definition":"已知总量和各部分之比，且这些部分合起来等于总量时，各部分的量等于总量乘以该部分份数占总份数的比例。","explanation":"员工只在部门之间调动，总人数仍为210。调动后的甲、丙、丁共占10份，每份21人，因此甲63人、丁84人。甲人数未变，原丁比甲少10人，原有53人。乙并入丁的人数为84−53＝31，再加上调到丙的20人，原乙共有51人。","evidence":"甲、丙、丁三个部门的员工数之比为3：3：4","doubt":"","references":[]},{"origin":"k-a4296054a0813f27","title":"按比例分配","qs":["国考 2025 行政执法 行测#67"],"definition":"已知总量和各部分的比时，先用总量除以总份数求出每份的量，再乘以各部分对应的份数。","explanation":"员工调动只改变部门归属，总人数仍为210人。调动后甲、丙、丁共有3＋3＋4＝10份，每份21人，甲有63人，丁有84人。甲的人数未变，原来比丁多10人，所以原丁有53人。丁增加的31人与调到丙的20人都来自乙，因此原乙有51人，选C。","evidence":"甲、丙、丁三个部门的员工数之比为3：3：4","doubt":"","references":[]},{"origin":"k-b186dfe3d16fad0d","title":"按比例分配","qs":["国考 2023 地市级 行测#68"],"definition":"按比例分配时，个人所得等于可分配总量乘以个人在分配依据中所占的比例。","explanation":"按本题约定，个人分红等于当年利润乘以40%，再乘以个人投资占比。甲各年的分配系数相同，因此其第二年分红是第三年的一半，意味着第二年利润也是第三年的一半。第三年比第二年多300万元，故两年利润分别为600万元和300万元，第一年利润为600÷3＝200万元。第二年比第一年多出的100万元利润中，有40万元用于分配，甲从中多得20万元，故甲的投资占比为50%，乙的投资占比也为50%，选B。","evidence":"40%按二人投资比例分配","doubt":"","references":[]},{"origin":"k-ce58fd32d8d4d9e9","title":"按比例分配","qs":["国考 2023 副省级 行测#73"],"definition":"按比例分配时，个人所得等于可分配总量乘以个人所占比例。若只拿出总量的一部分分配，先按约定比例求出可分配总量。","explanation":"本题每年只拿出利润的40%分红，甲的投资占比也固定，所以甲的分红始终等于当年利润乘以同一个系数。甲第二年的分红是第三年的一半，第二年利润也就是第三年的一半。结合两年利润相差300万元，得第二年和第三年利润分别为300万元和600万元，第一年利润为200万元。前两年可分配利润相差40万元，甲多分得20万元，故甲、乙各占50%，对应B项。","evidence":"40%按二人投资比例分配","doubt":"","references":[]}]},"questions":{"国考 2023 副省级 行测#73":{"paper":"国考 2023 副省级 行测","n":73,"mod":"数量关系","src":["503793642e845de9795f.pdf",13],"asrc":["ecade1ff5af69283232e.pdf",22],"card":"29ff74f14f6c672d4875465e","links":[{"id":"k-4f0ccba171d29d0b","role":"解题依据","why":"每人的分红等于当年利润乘以可分配比例，再乘以该人的投资占比。"}]},"国考 2023 地市级 行测#68":{"paper":"国考 2023 地市级 行测","n":68,"mod":"数量关系","src":["64bc3a15d27a04e94940.pdf",12],"asrc":["f3ab652d8e31c5bbdabc.pdf",21],"card":"db3c173891b9e15d89ecaa7e","links":[{"id":"k-4f0ccba171d29d0b","role":"解题依据","why":"先取年度利润的可分配部分，再乘个人投资占比得到该年的分红。"}]},"国考 2025 地市级 行测#67":{"paper":"国考 2025 地市级 行测","n":67,"mod":"数量关系","src":["31f401e91aef8d11365d.pdf",11],"asrc":["8cece062c7c079b53130.pdf",21],"card":"af66575f1af313d73df08c8b","links":[{"id":"k-4f0ccba171d29d0b","role":"解题依据","why":"调动前后员工总数相同，可用调动后的比例和总人数确定各部门人数。"}]},"国考 2025 行政执法 行测#67":{"paper":"国考 2025 行政执法 行测","n":67,"mod":"数量关系","src":["d8efe4e19862104d89c8.pdf",11],"asrc":["e2c4b1970d2b49eac0fd.pdf",22],"card":"df931d2ad2fbd88ffe35688a","links":[{"id":"k-4f0ccba171d29d0b","role":"解题依据","why":"以调动前后不变的总人数和调动后的份数比确定各部门人数。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-4f0ccba171d29d0b":[["国考 2023 副省级 行测#73","国考 2023 地市级 行测#68"],["国考 2025 地市级 行测#67","国考 2025 行政执法 行测#67"]]}};
